<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue';
import { Meteor } from 'meteor/meteor';
import { Tracker } from 'meteor/tracker';
import { useRoute, useRouter, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router';
import { CampaignSignals, InviteSignals } from '/imports/api/campaigns/signals';
import MarkdownText from '/imports/client/ui/components/MarkdownText.vue';
import CampaignImage from '/imports/client/ui/components/CampaignImage.vue';
const windowRef = window;
const route = useRoute(), router = useRouter();
const games = ref<any[]>([]), invitations = ref<any[]>([]), data = ref<any>(null), entry = ref<any>(null);
const error = ref(''), notice = ref(''), busy = ref(false), editing = ref(false), conflict = ref<any>(null);
const section = ref('overview'), query = ref(''), page = ref(0), form = ref<any>({}), baseline = ref('');
const createOpen = ref(false), gameName = ref(''), gameDescription = ref('');
const settingsOpen = ref(false), settings = ref<any>({}), membersOpen = ref(false), inviteName = ref(''), inviteRole = ref('player'), pending = ref<any[]>([]);
const historyOpen = ref(false), revisions = ref<any[]>([]), uploadOpen = ref(false), uploadForm = ref<any>({}), file = ref<any>(null);
const imageOpen = ref<any>(null), zoom = ref(100), assetEdit = ref<any>(null), galleryCategory = ref('');
const gameId = computed(() => String(route.params.campaignId || '')), userId = ref(Meteor.userId());
const campaign = computed(() => data.value?.campaign);
const sections = [{ value: 'overview', title: 'Overview' }, { value: 'pc', title: 'Player Characters' }, { value: 'npc', title: 'NPCs' }, { value: 'location', title: 'Locations' }, { value: 'place', title: 'Places' }, { value: 'journal', title: 'Journal' }, { value: 'artwork', title: 'Artwork' }, { value: 'trash', title: 'Trash' }];
const types = sections.filter(s => ['pc', 'npc', 'location', 'place', 'journal'].includes(s.value));
const locationOptions = computed(() => (data.value?.entries || []).filter((e: any) => ['location', 'place'].includes(e.type) && e._id !== form.value.entryId && !e.deleted).map((e: any) => ({ title: e.title, value: e._id })));
const relatedOptions = computed(() => (data.value?.entries || []).filter((e: any) => e._id !== form.value.entryId && !e.deleted).map((e: any) => ({ title: e.title, value: e._id })));
const artOptions = computed(() => (data.value?.assets || []).map((a: any) => ({ title: a.name + (a.visibility === 'gm' ? ' · GM-only' : ''), value: a._id })));
const gallery = computed(() => (data.value?.assets || []).filter((a: any) => !galleryCategory.value || a.category === galleryCategory.value));
const dirty = computed(() => editing.value && JSON.stringify(form.value) !== baseline.value);
const breadcrumbs = computed(() => { const list = [], seen = new Set(); let p = entry.value; while (p?.parentId && !seen.has(p.parentId)) { seen.add(p.parentId); p = data.value?.entries.find((e: any) => e._id === p.parentId); if (p) list.unshift(p); } return list; });
const children = computed(() => (data.value?.entries || []).filter((e: any) => e.parentId === entry.value?._id && !e.deleted));
const attached = computed(() => (data.value?.assets || []).filter((a: any) => entry.value?.assetIds.includes(a._id)));
let generation = 0, searchTimer: any, poll: any, subscription: any, tracker: any, debounce: any;
const draftPrefix = () => `campaign-draft:${userId.value}:${gameId.value}:`;
const draftKey = () => draftPrefix() + (form.value.entryId || 'new');
function clearDrafts(prefix: string) { for (const key of Object.keys(sessionStorage)) if (key.startsWith(prefix)) sessionStorage.removeItem(key); }
async function call(name: string, arg?: any): Promise<any> { return Meteor.callAsync('campaigns.' + name, ...(arg === undefined ? [] : [arg])); }
function failure(e: any) { error.value = e.reason || e.message || 'This action could not be completed.'; }
function discardAllowed() { return !dirty.value || window.confirm('Keep your recovery draft and leave this editor?'); }
function clearDialogs() { historyOpen.value=false; revisions.value=[]; membersOpen.value=false; pending.value=[]; settingsOpen.value=false; settings.value={}; uploadOpen.value=false; uploadForm.value={}; imageOpen.value=null; assetEdit.value=null; }
function resetEditor() { editing.value = false; form.value = {}; baseline.value = ''; conflict.value = null; }
async function refresh() {
 const n = ++generation, id = gameId.value;
 try {
  const [list, invites] = await Promise.all([call('list'), call('invitations')]);
  if (n !== generation) return; games.value = list; invitations.value = invites;
  if (!id) { data.value = null; entry.value = null; return; }
  const fresh = await call('state', { campaignId: id, query: query.value, type: types.some(t => t.value === section.value) ? section.value : undefined, page: page.value, trash: section.value === 'trash' });
  if (n !== generation) return;
  if (data.value && fresh.campaign.role !== data.value.campaign.role) { clearDrafts(draftPrefix()); resetEditor(); clearDialogs(); }
  data.value = fresh;
  if (imageOpen.value && !fresh.assets.some((a: any) => a._id === imageOpen.value._id)) imageOpen.value = null;
  if (route.query.entry && section.value !== 'trash') {
   try { const opened = await call('entry', { campaignId: id, entryId: String(route.query.entry) }); if (n === generation) entry.value = opened; }
   catch { if (n === generation) { entry.value = null; clearDrafts(draftPrefix()); resetEditor(); clearDialogs(); } }
  } else entry.value = null;
 } catch (e: any) {
  if (n !== generation) return; failure(e); data.value = null; entry.value = null; imageOpen.value = null; clearDrafts(draftPrefix()); resetEditor(); clearDialogs();
 }
}
async function openGame(id: string) { if (!discardAllowed()) return; resetEditor(); section.value = 'overview'; query.value = ''; page.value = 0; error.value = ''; await router.push({ name: 'campaign', params: { campaignId: id } }); }
async function openEntry(id: string) { if (!discardAllowed()) return; resetEditor(); await router.push({ name: 'campaign', params: { campaignId: gameId.value }, query: { entry: id } }); }
async function chooseSection(value: string) { if (!discardAllowed()) return; resetEditor(); section.value = value; page.value = 0; await router.replace({ name: 'campaign', params: { campaignId: gameId.value } }); await refresh(); }
async function act(name: string, arg: any, success = '') {
 busy.value = true; error.value = ''; try { const result = await call(name, arg); notice.value = success; await refresh(); return result; } catch (e) { failure(e); } finally { busy.value = false; }
}
async function createGame() { const id = await act('create', { name: gameName.value, description: gameDescription.value }); if (id) { createOpen.value = false; gameName.value = ''; gameDescription.value = ''; await openGame(id); } }
function startEdit(existing?: any) {
 if (!discardAllowed()) return;
 form.value = existing ? { campaignId: gameId.value, entryId: existing._id, revision: existing.revision, type: existing.type, title: existing.title, body: existing.body, tags: existing.tags, kind: existing.kind, parentId: existing.parentId, relatedIds: existing.relatedIds, assetIds: existing.assetIds, playerId: existing.playerId, ...(existing.nativeCharacterId ? { nativeCharacterId: existing.nativeCharacterId } : {}), visibility: existing.visibility, date: existing.date } : { campaignId: gameId.value, type: types.some(t => t.value === section.value) ? section.value : 'journal', title: '', body: '', tags: [], kind: '', parentId: null, relatedIds: [], assetIds: [], playerId: userId.value, visibility: 'shared', date: '' };
 baseline.value = JSON.stringify(form.value); conflict.value = null; editing.value = true;
 const saved = sessionStorage.getItem(draftKey()); if (saved && window.confirm('Recover your unsaved draft for this page?')) { try { form.value = JSON.parse(saved); } catch { sessionStorage.removeItem(draftKey()); } }
}
function recoverDraft() { startEdit(entry.value || undefined); }
async function save(confirmPublish = false) {
 busy.value = true; error.value = ''; conflict.value = null;
 try { const result = await call('save', { ...form.value, confirmPublish }); sessionStorage.removeItem(draftKey()); resetEditor(); await openEntry(result._id); await refresh(); notice.value = 'Page saved. Other members can see the shared changes.'; }
 catch (e: any) {
  if (e.error === 'campaign-publish' && !confirmPublish) { const details = e.details ? JSON.parse(e.details) : {}; if (window.confirm('Share these pages with all campaign members?\n\n' + (details.entries || []).join('\n') + '\n\nArtwork keeps its current audience.')) { busy.value = false; return save(true); } }
  else if (e.error === 'campaign-conflict' && form.value.entryId) { try { conflict.value = await call('entry', { campaignId: gameId.value, entryId: form.value.entryId }); } catch { /* Keep the draft until permissions are refreshed. */ } }
  failure(e);
 } finally { busy.value = false; }
}
async function showHistory() { try { revisions.value = await call('history', { campaignId: gameId.value, entryId: entry.value._id }); historyOpen.value = true; } catch (e) { failure(e); } }
async function restoreRevision(item: any, confirmPublish = false) {
 if (!window.confirm('Restore this revision’s title and text as a new revision? Current sharing, links and place hierarchy will stay in place.')) return;
 try { await call('restoreRevision', { campaignId: gameId.value, entryId: entry.value._id, revision: entry.value.revision, historyId: item._id, confirmPublish }); historyOpen.value = false; await refresh(); }
 catch (e: any) { if (e.error === 'campaign-publish' && !confirmPublish && window.confirm(e.reason + '\nPublish this historical text to the current audience?')) return restoreRevision(item, true); failure(e); }
}
async function moveTrash(item: any, restore = false) { if (window.confirm(restore ? 'Restore this branch? Independently trashed children stay in Trash.' : 'Move this page and its child places to Trash? A GM can recover them.')) { await act('trash', { campaignId: gameId.value, entryId: item._id, revision: item.revision, restore }); await router.replace({ name: 'campaign', params: { campaignId: gameId.value } }); await refresh(); } }
async function purge(item: any) { const confirm = window.prompt('Permanently delete this trashed branch and its history? Enter its page title to confirm. Artwork remains in the campaign.'); if (confirm) await act('purge', { campaignId: gameId.value, entryId: item._id, revision: item.revision, confirm }); }
async function showMembers() { pending.value = await call('invitations', { campaignId: gameId.value }); membersOpen.value = true; }
async function invitePlayer() { await act('invite', { campaignId: gameId.value, username: inviteName.value, role: inviteRole.value }, 'Invitation sent. The player must accept it from Campaigns.'); inviteName.value = ''; pending.value = await call('invitations', { campaignId: gameId.value }); }
async function memberAction(member: any, action: string, role?: string) { if (window.confirm(`${action === 'transfer' ? 'Transfer campaign ownership to' : action === 'remove' ? 'Remove' : 'Change role for'} ${member.username}?`)) await act('membership', { campaignId: gameId.value, userId: member.userId, action, ...(role ? { role } : {}) }); }
function showSettings() { settings.value = { campaignId: gameId.value, version: campaign.value.version, name: campaign.value.name, description: campaign.value.description, archived: campaign.value.archived, coverAssetId: campaign.value.coverAssetId, tabletopInput: campaign.value.tabletops.map((t: any) => t._id).join(', ') }; settingsOpen.value = true; }
async function saveSettings() { const { tabletopInput, ...arg } = settings.value; if (tabletopInput !== campaign.value.tabletops.map((t: any) => t._id).join(', ')) arg.tabletopIds = tabletopInput.split(',').map((v: string) => v.trim()).filter(Boolean); const result = await act('configure', arg, 'Campaign settings saved.'); if (!error.value) settingsOpen.value = false; }
async function deleteGame() { const confirm = window.prompt('Permanently delete this archived campaign, its notes and artwork? Enter the campaign name. Character sheets will remain.'); if (confirm) { await act('destroy', { campaignId: gameId.value, confirm }); if (!error.value || !data.value) { settingsOpen.value = false; await router.push({ name: 'campaigns' }); await refresh(); } } }
function showUpload() { file.value = null; uploadForm.value = { category: entry.value?.type === 'pc' || entry.value?.type === 'npc' ? 'portrait' : 'map', caption: '', alt: '', credits: '', visibility: entry.value?.restricted ? 'gm' : 'shared' }; uploadOpen.value = true; }
async function upload() {
 const chosen = Array.isArray(file.value) ? file.value[0] : file.value; if (!chosen) return;
 busy.value = true; error.value = '';
 try { if (chosen.size > 4 * 1024 ** 2) throw new Error('Choose an image up to 4 MiB.'); const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(chosen); }); await call('upload', { campaignId: gameId.value, ...(entry.value ? { entryId: entry.value._id, revision: entry.value.revision } : {}), name: chosen.name, data: base64, ...uploadForm.value }); uploadOpen.value = false; await refresh(); notice.value = 'Artwork uploaded to the campaign.'; } catch (e) { failure(e); } finally { busy.value = false; }
}
async function updateArtwork(publish = false) {
 if (publish && !window.confirm('Make this artwork visible in the shared gallery? Everyone in the campaign will be able to view and download it.')) return;
 await act('updateAsset', { campaignId: gameId.value, assetId: assetEdit.value._id, caption: assetEdit.value.caption, alt: assetEdit.value.alt, credits: assetEdit.value.credits, visibility: publish ? 'shared' : assetEdit.value.visibility, confirmPublish: publish }); if (!error.value) assetEdit.value = null;
}
function beforeUnload(event: BeforeUnloadEvent) { if (dirty.value) { event.preventDefault(); event.returnValue = ''; } }
onBeforeRouteLeave(() => discardAllowed());
onBeforeRouteUpdate(() => { if (!discardAllowed()) return false; resetEditor(); });
watch(form, () => { if (editing.value && dirty.value) { try { sessionStorage.setItem(draftKey(), JSON.stringify(form.value)); } catch { notice.value = 'Your browser could not store a recovery draft. Keep this editor open until you save.'; } } }, { deep: true });
watch(() => route.fullPath, () => { generation++; data.value = null; entry.value = null; void refresh(); });
watch(query, () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { page.value = 0; if (!editing.value && route.query.entry) void router.replace({name:'campaign',params:{campaignId:gameId.value}}); else void refresh(); }, 300); });
watch(page, () => void refresh());
onMounted(() => {
 subscription = Meteor.subscribe('campaigns.signals');
 let previousUser = Meteor.userId();
 tracker = Tracker.autorun(() => {
  const currentUser = Meteor.userId(), signals = CampaignSignals.find().fetch(), invites = InviteSignals.find().fetch(), ready = subscription.ready();
  if (currentUser !== previousUser) { clearDrafts(`campaign-draft:${previousUser}:`); resetEditor(); clearDialogs(); data.value = null; entry.value = null; imageOpen.value = null; previousUser = currentUser; userId.value = currentUser; }
  if (ready && gameId.value && !signals.some((s: any) => s._id === gameId.value)) { generation++; clearDrafts(draftPrefix()); resetEditor(); clearDialogs(); data.value = null; entry.value = null; imageOpen.value = null; }
  clearTimeout(debounce); debounce = setTimeout(() => void refresh(), 100);
 });
 poll = setInterval(() => { void call('invitations').then(value => { invitations.value = value; }).catch(() => {}); }, 10000);
 window.addEventListener('beforeunload', beforeUnload); void refresh();
});
onBeforeUnmount(() => { generation++; clearTimeout(searchTimer); clearTimeout(debounce); clearInterval(poll); tracker?.stop(); subscription?.stop(); window.removeEventListener('beforeunload', beforeUnload); });
</script>

<template>
<v-container fluid class="campaign-space">
 <div class="campaign-header"><div><h1>{{ campaign?.name || 'Campaigns' }}</h1><p>{{ campaign ? 'A shared notebook for your game' : 'Worlds, characters and stories, shared with your players' }}</p></div><div class="campaign-actions"><v-btn v-if="gameId" :to="{name:'campaigns'}" variant="outlined">All campaigns</v-btn><v-btn v-if="!gameId" color="primary" @click="createOpen=true">Create campaign</v-btn><template v-if="campaign"><v-chip>{{ campaign.role }}</v-chip><v-chip v-if="campaign.archived">Archived · read only</v-chip><v-btn v-if="campaign.manager" variant="outlined" @click="showMembers">Members &amp; invitations</v-btn><v-btn v-if="campaign.manager" variant="outlined" @click="showSettings">Campaign settings</v-btn></template></div></div>
 <v-alert v-if="error" type="error" class="mb-4" role="alert">{{ error }}</v-alert><v-alert v-if="notice" type="info" closable class="mb-4" @click:close="notice=''">{{ notice }}</v-alert>
 <template v-if="!gameId">
  <v-card v-if="invitations.length" class="pa-5 mb-5"><h2>Invitations</h2><v-list><v-list-item v-for="invite in invitations" :key="invite._id" :title="invite.campaignName" :subtitle="'Invited as '+invite.role+' · expires '+new Date(invite.expiresAt).toLocaleDateString()"><template #append><v-btn :disabled="busy" @click="async()=>{const id=await act('accept',{inviteId:invite._id});if(id)openGame(id)}">Accept invitation</v-btn></template></v-list-item></v-list></v-card>
  <div class="campaign-grid"><v-card v-for="game in games" :key="game._id" class="pa-5"><campaign-image v-if="game.coverAssetId" class="campaign-cover" :campaign-id="game._id" :asset-id="game.coverAssetId" :version="game.version" :alt="game.name+' cover'"/><h2>{{ game.name }}</h2><p class="my-3">{{ game.description }}</p><p>{{ game.role }}<span v-if="game.archived"> · Archived</span></p><v-btn class="mt-4" variant="outlined" @click="openGame(game._id)">Open campaign</v-btn></v-card></div>
  <v-card v-if="!games.length" class="pa-6"><h2>Your next adventure starts here</h2><p class="my-4">Create a private campaign, then invite existing player accounts. Everyone can contribute shared notes, places and artwork. GMs can keep separate private pages.</p><p>Campaign profiles can link to DiceCloud character sheets. Joining a game does not change anyone’s sheet permissions.</p></v-card>
 </template>
 <template v-else-if="campaign">
  <div class="campaign-layout"><aside><v-card class="pa-3"><nav aria-label="Campaign sections"><button v-for="item in sections.filter(s=>s.value!=='trash'||campaign.manager)" :key="item.value" class="campaign-section" :class="{'is-selected':section===item.value}" @click="chooseSection(item.value)">{{ item.title }}</button></nav><v-text-field v-model="query" class="mt-4" label="Search this campaign" clearable hide-details/><v-btn v-if="!campaign.archived" block class="mt-4" color="primary" @click="startEdit()">Add page</v-btn><p class="campaign-small mt-4">Shared pages are editable by members. GM-only content stays with GMs.</p></v-card></aside>
  <main>
   <v-card v-if="editing" class="pa-5 campaign-editor"><div class="campaign-header"><h2>{{ form.entryId ? 'Edit page' : 'New page' }}</h2><v-chip>{{ form.visibility==='gm' ? 'GM-only' : 'Shared with game' }}</v-chip></div>
    <v-select v-model="form.type" label="Page type" :items="types" item-title="title" item-value="value" :disabled="!!form.entryId"/>
    <v-text-field v-model="form.title" label="Page title" maxlength="160"/>
    <div class="campaign-fields"><v-text-field v-model="form.kind" label="Kind (e.g. city, tavern, guild)"/><v-select v-if="campaign.manager" v-model="form.visibility" label="Audience" :items="[{title:'Shared with game',value:'shared'},{title:'GM-only',value:'gm'}]"/></div>
    <v-select v-if="form.type==='pc'" v-model="form.playerId" label="Player account" :items="campaign.members.map((m:any)=>({title:m.username,value:m.userId}))" :disabled="!campaign.manager"/>
    <v-text-field v-if="['pc','npc'].includes(form.type)&&!entry?.privateSheet" v-model="form.nativeCharacterId" label="Optional DiceCloud character ID" hint="Link only. Native sheet ownership and permissions stay unchanged." persistent-hint class="mb-4"/>
    <p v-if="entry?.privateSheet" class="mb-4">The linked native sheet is private. Editing this biography preserves that link.</p>
    <v-select v-if="['location','place'].includes(form.type)" v-model="form.parentId" label="Parent location" :items="locationOptions" clearable :disabled="!!form.entryId&&!campaign.manager"/>
    <v-text-field v-if="form.type==='journal'" v-model="form.date" label="Session date or in-world date"/>
    <v-combobox v-model="form.tags" label="Tags" multiple chips/>
    <v-select v-model="form.relatedIds" label="Related people, places and notes" :items="relatedOptions" multiple chips/>
    <v-select v-model="form.assetIds" label="Attached campaign artwork (order follows selection)" :items="artOptions" multiple chips/>
    <v-textarea v-model="form.body" label="Notes (Markdown)" rows="14" auto-grow counter="48000"/>
    <p class="campaign-small">{{ dirty ? 'Unsaved changes · recovery draft kept in this browser session' : 'No unsaved changes' }}</p>
    <v-alert v-if="conflict" type="warning" class="my-4"><h3>A newer version is available</h3><p>Your draft above has been kept. Compare and merge the current text below before saving.</p><v-textarea :model-value="conflict.body" label="Current saved text" readonly rows="8"/><v-btn @click="form.revision=conflict.revision;conflict=null">I’ve merged changes; use latest revision</v-btn></v-alert>
    <div class="campaign-actions mt-4"><v-btn :loading="busy" :disabled="busy||!!conflict" color="primary" @click="save()">Save page</v-btn><v-btn :disabled="busy" @click="()=>{if(discardAllowed())resetEditor()}">Close editor</v-btn></div>
   </v-card>
   <template v-else>
    <v-card v-if="entry" class="pa-5 campaign-article"><div class="campaign-breadcrumb"><button @click="chooseSection('overview')">{{ campaign.name }}</button><template v-for="p in breadcrumbs" :key="p._id"> / <button @click="openEntry(p._id)">{{ p.title }}</button></template></div><div class="campaign-header"><div><h2>{{ entry.title }}</h2><p>{{ types.find(t=>t.value===entry.type)?.title }}<span v-if="entry.kind"> · {{ entry.kind }}</span></p></div><v-chip>{{ entry.restricted ? 'GM-only' : 'Shared with game' }}</v-chip></div><p v-if="entry.date" class="mb-3">{{ entry.date }}</p><div class="campaign-actions mb-5"><v-btn v-if="entry.canEdit" variant="outlined" @click="startEdit(entry)">Edit page</v-btn><v-btn variant="text" @click="showHistory">Revision history</v-btn><v-btn v-if="entry.canEdit" variant="text" @click="showUpload">Add artwork</v-btn><v-btn v-if="campaign.manager&&!campaign.archived" variant="text" @click="moveTrash(entry)">Move to Trash</v-btn><v-btn v-if="entry.nativeCharacterId" variant="outlined" :to="'/character/'+entry.nativeCharacterId">Open character sheet</v-btn></div>
     <markdown-text class="campaign-prose" :markdown="entry.body"/><div v-if="attached.length" class="campaign-grid mt-5"><button v-for="a in attached" :key="a._id" class="campaign-art" @click="imageOpen=a;zoom=100"><campaign-image :campaign-id="gameId" :asset-id="a._id" :version="campaign.version" :alt="a.alt||a.name"/><strong>{{ a.caption||a.name }}</strong></button></div>
     <div v-if="children.length" class="mt-5"><h3>Places inside this location</h3><v-btn v-for="child in children" :key="child._id" variant="text" @click="openEntry(child._id)">{{ child.title }}</v-btn></div><div v-if="entry.relatedIds.length" class="mt-5"><h3>Related entries</h3><v-btn v-for="key in entry.relatedIds" :key="key" variant="text" @click="openEntry(key)">{{ data.entries.find((e:any)=>e._id===key)?.title }}</v-btn></div><p class="campaign-small mt-5">Revision {{ entry.revision }} · Last saved {{ new Date(entry.updatedAt).toLocaleString() }} by {{ campaign.members.find((m:any)=>m.userId===entry.updatedBy)?.username||'a former member' }}</p>
    </v-card>
    <v-card v-else-if="section==='overview'&&!query" class="pa-5"><campaign-image v-if="campaign.coverAssetId" class="campaign-cover" :campaign-id="gameId" :asset-id="campaign.coverAssetId" :version="campaign.version" :alt="campaign.name+' cover'"/><h2>Game overview</h2><markdown-text class="campaign-prose my-4" :markdown="campaign.description"/><h3>Players</h3><p class="my-3">{{ campaign.members.map((m:any)=>m.username+' ('+m.role+')').join(', ') }}</p><h3>Recent visible changes</h3><v-list><v-list-item v-for="recent in data.recent" :key="recent._id" :title="recent.title" :subtitle="new Date(recent.updatedAt).toLocaleString()" @click="openEntry(recent._id)"/></v-list><div v-if="campaign.tabletops.length"><h3>Linked encounters</h3><v-btn v-for="t in campaign.tabletops" :key="t._id" :to="'/tabletop/'+t._id" variant="text">{{ t.name }}</v-btn></div><v-btn v-if="campaign.role!=='owner'" class="mt-5" variant="outlined" @click="async()=>{if(windowRef.confirm('Leave this campaign? Your notes and artwork stay with the group.')){await act('membership',{campaignId:gameId,userId,action:'leave'});router.push({name:'campaigns'})}}">Leave campaign</v-btn></v-card>
    <v-card v-else-if="section==='artwork'" class="pa-5"><div class="campaign-header"><h2>Artwork</h2><v-btn v-if="!campaign.archived" @click="showUpload">Upload artwork</v-btn></div><p class="mb-4">Portraits, maps and illustrations · {{ Math.ceil(campaign.storageUsed/1024) }} KiB of 25 MiB used</p><v-select v-model="galleryCategory" label="Artwork category" :items="[{title:'All artwork',value:''},{title:'Portraits',value:'portrait'},{title:'Maps',value:'map'},{title:'Illustrations',value:'illustration'}]"/><div class="campaign-grid"><v-card v-for="a in gallery.slice(page*20,page*20+20)" :key="a._id" class="pa-3"><button class="campaign-art" @click="imageOpen=a;zoom=100"><campaign-image :campaign-id="gameId" :asset-id="a._id" :version="campaign.version" :alt="a.alt||a.name"/><strong>{{ a.name }}</strong></button><p>{{ a.caption }}</p><p class="campaign-small">{{ a.category }} · {{ a.visibility==='gm'?'GM-only':'Shared' }}<span v-if="a.credits"> · {{ a.credits }}</span></p><v-btn v-if="!campaign.archived" variant="text" @click="assetEdit={...a}">Edit artwork details</v-btn><v-btn v-if="campaign.manager&&!campaign.archived" variant="text" @click="()=>{if(windowRef.confirm('Delete this artwork if it is no longer attached to any page or cover?'))act('removeAsset',{campaignId:gameId,assetId:a._id})}">Delete unused artwork</v-btn></v-card></div><div class="campaign-actions mt-4"><v-btn :disabled="!page" @click="page--">Previous</v-btn><v-btn :disabled="(page+1)*20>=gallery.length" @click="page++">Next</v-btn></div></v-card>
    <v-card v-else class="pa-5"><h2>{{ section==='trash'?'Campaign Trash':query?'Search results':sections.find(s=>s.value===section)?.title }}</h2><p class="my-3">{{ data.total }} visible pages</p><p v-if="section==='trash'">Trash stays recoverable until a GM explicitly purges it. Artwork remains in the gallery until separately removed.</p><v-list><v-list-item v-for="result in data.results" :key="result._id" :title="result.title" :subtitle="(result.kind?result.kind+' · ':'')+result.snippet" class="campaign-result" @click="section!=='trash'&&openEntry(result._id)"><template #append><template v-if="section==='trash'"><v-btn :disabled="campaign.archived" variant="text" @click.stop="moveTrash(result,true)">Restore branch</v-btn><v-btn :disabled="campaign.archived" variant="text" @click.stop="purge(result)">Purge</v-btn></template><v-chip v-else-if="result.restricted">GM-only</v-chip></template></v-list-item></v-list><div class="campaign-actions mt-4"><v-btn :disabled="!page" @click="page--">Previous</v-btn><span>{{ page+1 }}</span><v-btn :disabled="(page+1)*25>=data.total" @click="page++">Next</v-btn></div></v-card>
   </template>
  </main></div>
 </template>
 <v-dialog v-model="createOpen" max-width="650"><v-card title="Create campaign"><v-card-text><v-text-field v-model="gameName" label="Campaign name"/><v-textarea v-model="gameDescription" label="Game description (Markdown)"/><p>Private and invitation-only. Invite players after creating the game.</p><v-alert v-if="error" type="error">{{ error }}</v-alert></v-card-text><v-card-actions><v-btn :disabled="busy||!gameName.trim()" @click="createGame">Create campaign</v-btn><v-btn @click="createOpen=false">Cancel</v-btn></v-card-actions></v-card></v-dialog>
 <v-dialog v-model="membersOpen" max-width="800"><v-card title="Members & invitations"><v-card-text><v-alert v-if="error" type="error" class="mb-3">{{ error }}</v-alert><p>Invitations go to existing accounts. Players accept them from their Campaigns page. Invitations expire after seven days.</p><v-text-field v-model="inviteName" label="Player account username" class="mt-4"/><v-select v-if="campaign?.role==='owner'" v-model="inviteRole" label="Campaign role" :items="['player','gm']"/><v-btn :disabled="busy||!inviteName.trim()||campaign?.archived" @click="invitePlayer">Send invitation</v-btn><v-list><v-list-item v-for="member in campaign?.members" :key="member.userId" :title="member.username" :subtitle="member.role"><template #append><template v-if="member.role!=='owner'"><v-btn v-if="campaign?.role==='owner'" size="small" @click="memberAction(member,'role',member.role==='gm'?'player':'gm')">{{ member.role==='gm'?'Make player':'Make GM' }}</v-btn><v-btn v-if="campaign?.role==='owner'" size="small" @click="memberAction(member,'transfer')">Transfer ownership</v-btn><v-btn v-if="campaign?.role==='owner'||member.role==='player'" size="small" @click="memberAction(member,'remove')">Remove member</v-btn></template></template></v-list-item></v-list><h3>Pending invitations</h3><v-list><v-list-item v-for="invite in pending" :key="invite._id" :title="invite.username" :subtitle="invite.role"><template #append><v-btn @click="async()=>{await act('revokeInvite',{campaignId:gameId,inviteId:invite._id});pending=await call('invitations',{campaignId:gameId})}">Revoke invitation</v-btn></template></v-list-item></v-list></v-card-text><v-card-actions><v-btn @click="membersOpen=false">Close</v-btn></v-card-actions></v-card></v-dialog>
 <v-dialog v-model="settingsOpen" max-width="750"><v-card title="Campaign settings"><v-card-text><v-alert v-if="error" type="error">{{ error }}</v-alert><v-text-field v-model="settings.name" label="Campaign name"/><v-textarea v-model="settings.description" label="Game description (Markdown)"/><v-select v-model="settings.coverAssetId" label="Campaign cover" clearable :items="data?.assets.filter((a:any)=>a.visibility==='shared'&&a.standalone).map((a:any)=>({title:a.name,value:a._id}))||[]"/><v-text-field v-model="settings.tabletopInput" label="Optional native tabletop IDs, separated by commas" hint="You must already have access. Members retain their existing encounter permissions." persistent-hint/><v-checkbox v-model="settings.archived" label="Archive campaign (members can still read)"/><v-btn v-if="campaign?.role==='owner'&&campaign?.archived" color="error" @click="deleteGame">Permanently delete campaign</v-btn></v-card-text><v-card-actions><v-btn :loading="busy" @click="saveSettings">Save settings</v-btn><v-btn @click="settingsOpen=false">Close</v-btn></v-card-actions></v-card></v-dialog>
 <v-dialog v-model="historyOpen" max-width="900"><v-card title="Revision history"><v-card-text><v-alert v-if="error" type="error">{{ error }}</v-alert><p>Up to 50 revisions per page, within the campaign’s history budget. Restores create a new revision.</p><v-expansion-panels class="mt-4"><v-expansion-panel v-for="r in revisions" :key="r._id" :title="'Revision '+r.revision+' · '+new Date(r.savedAt).toLocaleString()"><v-expansion-panel-text><h3>{{ r.title }}</h3><markdown-text class="campaign-prose my-3" :markdown="r.body"/><v-btn v-if="entry?.canEdit" @click="restoreRevision(r)">Restore this text</v-btn></v-expansion-panel-text></v-expansion-panel></v-expansion-panels></v-card-text><v-card-actions><v-btn @click="historyOpen=false">Close</v-btn></v-card-actions></v-card></v-dialog>
 <v-dialog v-model="uploadOpen" max-width="700"><v-card title="Upload campaign artwork"><v-card-text><v-alert v-if="error" type="error">{{ error }}</v-alert><p>JPEG, PNG or WebP · up to 4 MiB and 24 megapixels. Originals stay with the campaign. {{ entry ? 'Attaching to: '+entry.title : 'Adding to the campaign gallery.' }}</p><v-file-input v-model="file" label="Image file" accept="image/jpeg,image/png,image/webp"/><v-select v-model="uploadForm.category" label="Artwork kind" :items="['portrait','map','illustration']"/><v-select v-if="campaign?.manager" v-model="uploadForm.visibility" label="Artwork audience" :disabled="!!entry?.restricted" :items="[{title:'Shared with game',value:'shared'},{title:'GM-only',value:'gm'}]"/><v-text-field v-model="uploadForm.caption" label="Caption"/><v-text-field v-model="uploadForm.alt" label="Alternative text"/><v-text-field v-model="uploadForm.credits" label="Artist or source credit"/><v-progress-linear v-if="busy" indeterminate/><p v-if="busy">Validating and uploading artwork…</p></v-card-text><v-card-actions><v-btn :loading="busy" :disabled="busy||!file" @click="upload">Upload artwork</v-btn><v-btn :disabled="busy" @click="uploadOpen=false">Cancel</v-btn></v-card-actions></v-card></v-dialog>
 <v-dialog :model-value="!!assetEdit" max-width="650" @update:model-value="value=>{if(!value)assetEdit=null}"><v-card v-if="assetEdit" title="Artwork details"><v-card-text><v-alert v-if="error" type="error">{{ error }}</v-alert><v-text-field v-model="assetEdit.caption" label="Caption"/><v-text-field v-model="assetEdit.alt" label="Alternative text"/><v-text-field v-model="assetEdit.credits" label="Artist or source credit"/><v-select v-if="campaign?.manager" v-model="assetEdit.visibility" label="Audience" :items="['shared','gm']"/><v-btn v-if="campaign?.manager" variant="outlined" @click="updateArtwork(true)">Publish in shared gallery</v-btn></v-card-text><v-card-actions><v-btn :disabled="busy" @click="updateArtwork(false)">Save details</v-btn><v-btn @click="assetEdit=null">Close</v-btn></v-card-actions></v-card></v-dialog>
 <v-dialog :model-value="!!imageOpen" fullscreen @update:model-value="value=>{if(!value)imageOpen=null}"><v-card v-if="imageOpen" class="campaign-lightbox"><v-toolbar><v-toolbar-title>{{ imageOpen.caption||imageOpen.name }}</v-toolbar-title><v-btn @click="zoom=100">Fit</v-btn><v-btn @click="imageOpen=null">Close artwork</v-btn></v-toolbar><v-slider v-model="zoom" min="100" max="400" step="25" label="Map zoom" thumb-label class="mx-6 mt-4"/><div class="campaign-map-scroll"><campaign-image :campaign-id="gameId" :asset-id="imageOpen._id" :version="campaign.version" :original="true" :alt="imageOpen.alt||imageOpen.name" :style="zoom===100?{maxWidth:'100%',maxHeight:'75vh',width:'auto'}:{width:zoom+'%',maxWidth:'none',height:'auto'}"/></div><p class="pa-4">{{ imageOpen.caption }} {{ imageOpen.credits }}</p></v-card></v-dialog>
</v-container>
</template>
<style scoped>
.campaign-space{max-width:1720px;margin:auto;padding:24px}.campaign-header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}.campaign-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.campaign-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:24px;align-items:start}.campaign-layout main{min-width:0}.campaign-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:18px}.campaign-section{display:block;text-align:left;width:100%;padding:12px;color:inherit;border-radius:4px;cursor:pointer}.campaign-section:hover,.is-selected{background:#b99b6433}.campaign-section:focus-visible,.campaign-art:focus-visible{outline:2px solid currentColor}.campaign-prose{font-size:1.05rem;line-height:1.75;overflow-wrap:anywhere}.campaign-prose :deep(p){margin-bottom:14px}.campaign-prose :deep(ul),.campaign-prose :deep(ol){padding-left:24px;margin:12px 0}.campaign-prose :deep(table){display:block;overflow-x:auto;max-width:100%;border-collapse:collapse}.campaign-prose :deep(td),.campaign-prose :deep(th){padding:8px;border:1px solid #a58c61;overflow-wrap:normal}.campaign-cover{display:block;max-height:280px;width:100%;object-fit:cover;margin-bottom:20px;border-radius:6px}.campaign-art{display:block;width:100%;text-align:left;color:inherit;cursor:pointer}.campaign-art img{display:block;width:100%;height:200px;object-fit:contain;margin-bottom:10px}.campaign-small{font-size:.85rem;line-height:1.5;opacity:.85}.campaign-breadcrumb{font-size:.9rem;margin-bottom:16px}.campaign-breadcrumb button{text-decoration:underline;color:inherit}.campaign-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.campaign-result :deep(.v-list-item-subtitle){white-space:normal;line-height:1.6}.campaign-map-scroll{overflow:auto;height:calc(100vh - 190px);background:#111b2a;display:block;text-align:center;touch-action:pan-x pan-y}.campaign-map-scroll img{vertical-align:top}.campaign-editor :deep(textarea){font-family:inherit;line-height:1.65}@media(max-width:850px){.campaign-space{padding:12px}.campaign-layout{grid-template-columns:1fr}.campaign-layout nav{display:flex;flex-wrap:wrap}.campaign-section{width:auto;padding:10px}.campaign-fields{grid-template-columns:1fr}.campaign-actions :deep(.v-btn){max-width:100%;white-space:normal}.campaign-header h1{font-size:1.8rem;overflow-wrap:anywhere}}
</style>
